-- Driver for tests/test_lua_fast_policy.py: runs the Lua core on cases generated by Python and writes the
-- outcomes, so Python can compare them with fast_policy.py, json, hashlib and native_switch.
-- Usage: lua5.1 differential.lua <cases.json> <results.json>
local here=(arg[0]:match('^(.*)/[^/]*$') or '.')
package.path=here..'/../../files/usr/lib/homensai-vpn/lua/?.lua;'..package.path
local fp=require('fast_policy')
local json=require('canon')
local kernel=require('kernel')
local journal=require('journal')
local switch=require('instant_switch')
json.configure({runtime=os.getenv('HOMENSAI_TEST_RUNTIME') or '/tmp'})

local function read(path) local f=assert(io.open(path,'rb'));local s=f:read('*a');f:close();return s end
local function write(path,s) local f=assert(io.open(path,'wb'));f:write(s);f:close() end

local function unhex(h) return (string.gsub(h,'%x%x',function(x) return string.char(tonumber(x,16)) end)) end
local function tohex(s) return (string.gsub(s,'.',function(c) return string.format('%02x',string.byte(c)) end)) end

local function list(t) local out={};for i=1,#t do out[i]=t[i] end;return json.array(out) end

-- {"ok": ...} | {"unsupported": code} | {"refused": code} | {"error": message}
local function outcome(fn,...)
  local ok,a,b,c=pcall(fn,...)
  if ok then return json.object({ok=list({a,b,c})}) end
  if fp.is_unsupported(a) then return json.object({unsupported=a.code}) end
  if kernel.is_refused(a) or journal.is_refused(a) or getmetatable(a)==switch.Refused then return json.object({refused=a.code}) end
  return json.object({error=tostring(type(a)=='table' and (a.code or 'table') or a)})
end

local function from_bits(h)  -- IEEE-754 double from 16 hex digits, exactly
  local hi,lo=tonumber(h:sub(1,8),16),tonumber(h:sub(9,16),16)
  local negative=hi>=2^31
  if negative then hi=hi-2^31 end
  local e=math.floor(hi/2^20);local m=(hi%2^20)*2^32+lo
  local x=(e==0) and math.ldexp(m,-1074) or math.ldexp(2^52+m,e-1075)
  if negative then x=-x end
  return x
end

local cases=json.decode(read(arg[1]))
local results=json.object({})

local function each(name,fn)
  local rows=cases[name]
  if not rows then return end
  local out={}
  for i=1,#rows do out[i]=fn(rows[i]) end
  results[name]=json.array(out)
end

each('uci_rules',function(text)
  return outcome(function() local order,lt,lm=fp.uci_rules(text);return list(order),lt,lm end)
end)
each('plan',function(c)
  return outcome(function()
    local payload,old,changed=fp.plan(c[1],{unpack(c[2])},c[3],c[4]);return payload,old,changed
  end)
end)
each('mark_of',function(c) return outcome(fp.mark_of,c[1],c[2]) end)
each('prepare',function(c)
  return outcome(function()
    local order,lt,lm=fp.uci_rules(kernel.decode(unhex(c[1])))
    local p=kernel.prepare({order=order,local_tunnel=lt,local_mark=lm},kernel.snapshot(unhex(c[2])))
    return json.object({order=list(order),local_tunnel=lt,local_mark=lm,
      payload_hex=tohex(p.payload),old_first=p.old_first,changed=p.changed,old_mark=p.old_mark or json.null})
  end)
end)
each('decode',function(h) return tohex(kernel.decode(unhex(h))) end)
each('repr',function(h) return json.repr_float(from_bits(h)) end)
each('json',function(text)
  local ok,value=pcall(json.decode,text)
  if not ok then return json.object({error=tostring(value)}) end
  local encoded=json.encode(value)
  return json.object({ok=encoded,sha256=json.sha256(encoded)})
end)
each('sha256',function(h) return json.sha256(unhex(h)) end)
each('reorder',function(c)
  return outcome(function()
    local moves,expected=switch.reorder_moves({unpack(c[1])},{unpack(c[2])})
    local rows={}
    for i,m in ipairs(moves) do rows[i]=list({m.id,m.index}) end
    return json.array(rows),list(expected)
  end)
end)

-- kernel_policy.parse_mangle + fields of every rule: {"ok":[{chain:[tokens...]}, [fields...]]}
each('parse_mangle',function(text)
  return outcome(function()
    local chains,order=kernel.parse_mangle(kernel.snapshot(text))
    local out,all=json.object({}),{}
    for _,name in ipairs(order) do
      local rows={}
      for i,rule in ipairs(chains[name]) do
        rows[i]=list(rule)
        local f=kernel.fields(rule)
        if f['-m'] then f['-m']=list(f['-m']) end
        all[#all+1]=json.object(f)
      end
      out[name]=json.array(rows)
    end
    return out,json.array(all)
  end)
end)
-- Journal jobs on real files: read what Python wrote, change it like the instant switch does, write.
local fs={read=function(path) local f=io.open(path,'rb');if not f then return nil end;local s=f:read('*a');f:close();return s end,
          write_atomic=function(path,text) write(path..'.pending',text);assert(os.rename(path..'.pending',path)) end}
each('journal_hold',function(job)
  return outcome(function()
    local value=journal.read({fs=fs,path=job.input})
    local template=journal.read({fs=fs,path=job.input})
    local now=json.number(job.now)
    value.phase='HELD-ON-RESERVE';value.reason='OPERATOR-MANUAL';value.confirmed=json.float(now)
    value.reserve_healthy=true;value.instant_seconds=json.float(json.number(job.instant))
    journal.write({fs=fs,path=job.output,now=function() return now end,template=template},value)
    return journal.digest(value)
  end)
end)
each('journal_fresh',function(job)
  return outcome(function()
    local value=json.decode(job.value)  -- a journal Lua builds itself (no delegated records)
    local now=json.number(job.now)
    journal.write({fs=fs,path=job.output,now=function() return now end},value)
    return journal.digest(value)
  end)
end)
each('journal_read',function(path)
  return outcome(function() local v=journal.read({fs=fs,path=path});return json.encode(v) end)
end)

write(arg[2],json.encode(results))
